    dict(title='Алгоритмы обработки массивов', short='Алгоритмы обработки массивов', desc='Научитесь хранить наборы данных, находить нужные элементы и создавать алгоритмы их обработки.', icon='array', tag='Глава 1', url='arrays.html', color='violet', range='§ 3–7', pages='22–58'),
    dict(title='Компьютер как универсальное устройство обработки информации', short='Компьютер и представление данных', desc='Разберитесь, как устроен компьютер и как числа, тексты, изображения и звук становятся данными.', icon='monitor', tag='Глава 2', url='computer.html', color='mint', range='§ 8–15', pages='59–113'),
