def icon(name, cls=''):
    return f'<svg class="icon {cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{PATHS[name]}</svg>'

def layout(title, content, prefix='', active='course', crumb='10 класс', bodyclass=''):
    def link(url): return prefix+url
    nav = ''
    for key, url, ic, label in [('course','Программисты.html','grid','Обзор курса'),('book','textbook.html','book','Учебник'),('saved','saved.html','bookmark','Избранное')]:
        current = 'aria-current="page"' if active == key else ''
        count = '<span class="nav-count">15</span>' if key == 'course' else ''
        nav += f'<a class="nav-link {"active" if active == key else ""}" href="{link(url)}" {current}>{icon(ic)}<span>{label}</span>{count}</a>'
    chapters = ''.join(f'<a class="chapter-nav {"selected" if active == "group"+str(i) else ""}" href="{link(g["url"])}"><span class="chapter-number">{"↳" if i == 0 else "0"+str(i)}</span><span>{"Введение" if i == 0 else g["short"]}</span></a>' for i,g in enumerate(GROUPS))
    return f'''<!doctype html>
<html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} — Информатика · 10 класс</title><meta name="description" content="Информатика для 10 класса: темы по учебнику Котова, Лапо, Быкадорова и Войтехович, 2020. Конспекты, практика и самопроверка."><meta name="theme-color" content="#2563eb"><link rel="icon" href="{link('assets/favicon.svg')}" type="image/svg+xml"><link rel="stylesheet" href="{link('assets/site.css')}"><script src="{link('assets/site.js')}" defer></script></head>
<body class="{bodyclass}" data-prefix="{prefix}"><a class="skip-link" href="#main">Перейти к содержанию</a>
<aside class="sidebar" id="navigation"><a class="brand" href="{link('index.html')}"><span class="brand-icon">{icon('code')}</span><span>информатика<span class="brand-sub">УЧИМСЯ ДУМАТЬ. СОЗДАЁМ.</span></span></a>
<div class="class-select"><span class="class-square">10</span><div><strong>10 класс</strong><small>Учебный курс</small></div><span class="status-dot"></span></div>
<p class="nav-label">ОБУЧЕНИЕ</p><nav aria-label="Основная навигация">{nav}</nav><p class="nav-label chapter-label">РАЗДЕЛЫ КУРСА</p><nav class="chapter-links" aria-label="Разделы курса">{chapters}<a class="chapter-nav" href="{link('appendix.html')}"><span class="chapter-number">+</span><span>Приложение и справочник</span></a></nav>
<div class="sidebar-bottom"><a class="safety-link" href="{link('safety.html')}">{icon('shield')} Техника безопасности {icon('external')}</a><div class="school"><span class="school-mark">67</span><span>Средняя школа №67<small>г. Гомель</small></span></div><p class="sidebar-note">Знания, которые открывают<br>новые возможности.</p></div></aside>
<div class="app"><header class="topbar"><div class="top-left"><button class="mobile-menu icon-button" aria-label="Открыть меню" aria-expanded="false" aria-controls="navigation">{icon('menu')}</button><span class="top-subject">Образовательный ресурс</span><span class="breadcrumb-divider">/</span><span class="breadcrumb">{e(crumb)}</span></div><nav class="grade-tabs" aria-label="Выбор класса"><a class="grade-active" href="{link('Программисты.html')}">10 класс</a><a href="{link('Бухгалтера.html')}" title="Существующий раздел 11 класса">11 класс {icon('external')}</a></nav></header>
<main id="main" class="main-content" tabindex="-1">{content}</main><footer class="footer"><span>© Средняя школа №67 г. Гомеля</span><span>Информатика · 10 класс <span class="footer-dot">•</span> Учимся шаг за шагом</span><a href="{link('safety.html')}">Правила работы с ПК {icon('external')}</a></footer></div><button class="menu-overlay" aria-label="Закрыть меню" hidden></button><div id="toast" class="toast" role="status"></div></body></html>'''

def write(path, text):
    p = ROOT/path
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')

def group_cards(prefix=''):
    cards=''
    for i,g in enumerate(GROUPS):
        n = len([x for x in LESSONS if x['group']==i])
        cards += f'''<a class="course-card {g['color']}" href="{prefix+g['url']}"><div class="card-top"><span class="topic-icon">{icon(g['icon'])}</span><span class="chapter-tag">{g['tag']}</span><span class="card-corner">{icon('arrow')}</span></div><h3>{g['title']}</h3><p>{g['desc']}</p><div class="card-meta"><span>{icon('book')} {n} {"темы" if n==2 else "тем"}</span><span>{g['range']}</span><span class="card-page">с. {g['pages']}</span></div><div class="card-progress"><span data-group-progress="{i}"></span></div></a>'''
    return cards

def lesson_rows(items, prefix='', search=False):
    rows=''
    for x in items:
        rows += f'''<article class="lesson-row" data-lesson-id="{x['id']}" data-group="{x['group']}" data-search="{e(x['title'].lower()+' '+x['desc'].lower())}"><a class="lesson-main" href="{prefix}lessons/{x['id']:02}.html"><span class="lesson-number">{x['id']:02}</span><span class="lesson-copy"><strong>{e(x['title'])}</strong><span>{e(x['desc'])}</span></span><span class="lesson-page">§ {x['id']} <i>·</i> с. {x['page']}–{x['end']}</span><span class="lesson-state" data-state="{x['id']}">{icon('chevron')}</span></a><button class="save-button icon-button" data-save="{x['id']}" aria-label="Добавить в избранное: {e(x['title'])}" aria-pressed="false" title="В избранное">{icon('bookmark')}</button></article>'''
    return rows

def dashboard(prefix=''):
    return f'''<div class="page-heading"><div><p class="eyebrow">ТВОЙ ПУТЬ В МИР ТЕХНОЛОГИЙ</p><h1>Информатика. <span>10 класс</span></h1><p class="page-description">Понимай, как всё устроено. Пробуй. Создавай своё.</p></div><a class="text-link heading-book" href="{prefix}textbook.html">{icon('book')} Об учебнике {icon('external')}</a></div>
<section class="hero" aria-labelledby="hero-title"><div class="hero-copy"><span class="hero-label"><span></span> ОТ ПЕРВЫХ АЛГОРИТМОВ — К БОЛЬШИМ ИДЕЯМ</span><h2 id="hero-title">Сложное становится<br><span>понятным.</span></h2><p>Алгоритмы, массивы и устройство компьютера.<br>Весь курс — по темам твоего учебника.</p><a class="button button-light" data-start href="{prefix}lessons/01.html">Начать обучение {icon('arrow')}</a><span class="hero-note">В своём темпе. Шаг за шагом.</span></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="floating-chip chip-top">{icon('code')} PascalABC.NET</span><div class="code-window"><div class="window-bar"><span></span><span></span><span></span><small>hello_world.pas</small></div><div class="code-lines"><div><i>01</i> <em>begin</em></div><div><i>02</i> <span>Writeln</span>(<b>'Привет, мир!'</b>);</div><div><i>03</i> <em>end.</em><span class="cursor"></span></div></div><div class="terminal-line"><span>›</span> Привет, мир! <span class="terminal-check">✓</span></div></div><div class="array-preview"><span>a[i]</span><b>3</b><b>1</b><b class="array-active">4</b><b>1</b><b>5</b><small>Думай алгоритмически {icon('spark')}</small></div><span class="floating-chip chip-bottom"><span class="tiny-green">✓</span> Всё начинается с первой строки</span></div></section>
<div class="overview-strip"><div>{icon('book')}<strong>3 раздела</strong><span>от основ к практике</span></div><div>{icon('grid')}<strong>15 тем</strong><span>по учебному пособию</span></div><div>{icon('code')}<strong>Практика</strong><span>в каждой теме</span></div><div>{icon('check')}<strong>Твой прогресс</strong><span><b data-completed-count>0</b> из 15 тем пройдено</span></div></div>
<section class="course-section" aria-labelledby="sections-title"><div class="section-heading"><div><span class="eyebrow">ПРОГРАММА ОБУЧЕНИЯ</span><h2 id="sections-title">Куда отправимся?</h2></div><span class="subtle">По учебнику · Котов и др., 2020</span></div><div class="course-grid">{group_cards(prefix)}</div></section>
<div class="dashboard-lower"><section class="topics-section" aria-labelledby="topics-title"><div class="section-heading"><div><h2 id="topics-title">Темы курса</h2><p class="subtle">Выбирай интересное или двигайся по порядку</p></div><span class="count-pill" data-result-count>15 тем</span></div><div class="search-box">{icon('search')}<input id="lesson-search" type="search" placeholder="Найти тему…" aria-label="Поиск темы"><kbd>/</kbd></div><div class="filter-tabs" role="group" aria-label="Фильтр тем"><button class="selected" data-filter="all" aria-pressed="true">Все темы</button><button data-filter="0" aria-pressed="false">Введение</button><button data-filter="1" aria-pressed="false">Массивы</button><button data-filter="2" aria-pressed="false">Компьютер</button></div><div class="lesson-list">{lesson_rows(LESSONS,prefix)}</div><div class="empty-state" data-empty hidden>{icon('search')}<h3>Ничего не нашлось</h3><p>Попробуй другое название или выбери все темы.</p><button class="button button-outline" data-reset-search>Сбросить поиск</button></div></section><aside class="right-column"><section class="textbook-card"><div class="mini-heading">ТВОЙ УЧЕБНИК <span class="pdf-badge">PDF</span></div><div class="book-display"><img src="{prefix}assets/textbook-10.png" alt="Обложка учебного пособия Информатика, 10 класс" width="491" height="638" loading="lazy"><span>10<span>класс</span></span></div><h3>Информатика</h3><p>В. М. Котов, А. И. Лапо,<br>Ю. А. Быкадоров, Е. Н. Войтехович</p><span class="book-edition">Народная асвета · 2020</span><a class="button button-outline full-width" href="{prefix}files/informatika-10.pdf" target="_blank" rel="noopener">Открыть учебник {icon('external')}</a></section><a class="reference-card" href="{prefix}appendix.html"><span class="reference-icon">{icon('file')}</span><h3>Всё под рукой</h3><p>Формулы, единицы измерения и справочные таблицы.</p><span class="text-link">В справочник {icon('arrow')}</span></a><a class="safety-card" href="{prefix}safety.html">{icon('shield')}<span><strong>Сначала — безопасность</strong><small>Правила работы за компьютером</small></span>{icon('chevron')}</a></aside></div>
<section class="bottom-banner"><span class="banner-icon">{icon('spark')}</span><div><h3>Не просто запоминай — разбирайся.</h3><p>Каждая решённая задача — ещё один шаг вперёд.</p></div><a href="{prefix}lessons/01.html">К первой теме {icon('arrow')}</a></section>'''

for path,prefix in [('index.html',''),('Программисты.html',''),('ИОР-Информатика.html',''),('!Index/index.html','../')]:
    write(path,layout('Обзор курса',dashboard(prefix),prefix))

for i,g in enumerate(GROUPS):
    items=[x for x in LESSONS if x['group']==i]
    content=f'''<a class="back-link" href="Программисты.html">← Все разделы</a><div class="chapter-hero {g['color']}"><div class="topic-icon">{icon(g['icon'])}</div><p class="eyebrow">{g['tag'].upper()} · {g['range']} · С. {g['pages']}</p><h1>{g['title']}</h1><p>{g['desc']}</p><a class="button button-primary" href="lessons/{items[0]['id']:02}.html">Начать раздел {icon('arrow')}</a></div><section class="chapter-content"><div class="section-heading"><h2>Темы раздела</h2><span class="subtle">{len(items)} тем · Конспект, практика, самопроверка</span></div><div class="lesson-list">{lesson_rows(items)}</div></section><div class="source-note">{icon('book')}<p>Раздел соответствует оглавлению прикреплённого учебного пособия. Конспекты и тренировочные задания подготовлены для сайта. Полный материал — <a href="files/informatika-10.pdf#page={items[0]['page']+1}" target="_blank" rel="noopener">в учебнике, с. {g['pages']}</a>.</p></div>'''
    write(g['url'],layout(g['title'],content,active='group'+str(i),crumb=g['tag']))

for x in LESSONS:
    g=GROUPS[x['group']]
    terms=''.join(f'<span>{e(t)}</span>' for t in x['terms'])
    theory=''.join(f'<p>{e(t)}</p>' for t in x['theory'])
    tasks=''.join(f'<li>{e(t)}</li>' for t in x['tasks'])
    code=f'<div class="example-code"><div>PascalABC.NET <button data-copy class="copy-button">Копировать</button></div><pre><code>{e(x["code"])}</code></pre></div>' if 'code' in x else ''
    options=''.join(f'<label class="quiz-option"><input type="radio" name="answer" value="{j}" required><span>{e(o)}</span></label>' for j,o in enumerate(x['quiz']['options']))
    prev=f'<a href="{x["id"]-1:02}.html">← Предыдущая тема</a>' if x['id']>1 else '<a href="../introduction.html">← К введению</a>'
    nex=f'<a href="{x["id"]+1:02}.html">Следующая тема {icon("arrow")}</a>' if x['id']<15 else '<a href="../appendix.html">В справочник →</a>'
    content=f'''<a class="back-link" href="../{g['url']}">← {g['tag']}: {g['short']}</a><div class="lesson-heading"><p class="eyebrow">{g['tag'].upper()} · § {x['id']} · С. {x['page']}–{x['end']}</p><h1>{e(x['title'])}</h1><p class="page-description">{e(x['desc'])}</p><div class="lesson-tools"><a class="text-link" href="../files/informatika-10.pdf#page={x['page']+1}" target="_blank" rel="noopener">{icon('book')} Читать в учебнике {icon('external')}</a><button class="text-link save-text" data-save="{x['id']}" aria-pressed="false">{icon('bookmark')}<span data-save-label>В избранное</span></button></div></div><div class="lesson-layout"><article class="lesson-article"><section id="theory" class="article-section"><span class="eyebrow">01 / РАЗБЕРЁМСЯ</span><h2>Кратко о главном</h2><div class="term-tags">{terms}</div>{theory}</section><section id="example" class="article-section"><span class="eyebrow">02 / ПОСМОТРИМ НА ПРИМЕРЕ</span><h2>{e(x['exampleTitle'])}</h2>{code}<div class="example-explanation">{e(x['example'])}</div></section><section id="practice" class="article-section"><span class="eyebrow">03 / ПОПРОБУЙ САМ</span><h2>Время практики</h2><p class="subtle">Выполни задания в тетради или в среде PascalABC.NET, если нужна программа.</p><ol class="practice-list">{tasks}</ol><details class="answer-details"><summary>Подсказки и ответы</summary><p>{e(x['answer'])}</p></details></section><section id="quiz" class="article-section"><span class="eyebrow">04 / ПРОВЕРЬ СЕБЯ</span><h2>Всё понятно?</h2><form class="quiz-form" data-correct="{x['quiz']['correct']}" data-explanation="{e(x['quiz']['explain'])}"><fieldset><legend>{e(x['quiz']['q'])}</legend>{options}</fieldset><button class="button button-primary" type="submit">Проверить ответ {icon('arrow')}</button><p class="quiz-feedback" role="status" hidden></p></form></section><div class="completion-panel"><span class="completion-icon">{icon('check')}</span><div><h3>Ещё одна тема позади!</h3><p>Разобрался с теорией и выполнил задания? Отметь свой прогресс.</p></div><button class="button button-primary" data-complete="{x['id']}" aria-pressed="false">Отметить пройденной</button></div><nav class="lesson-pagination" aria-label="Переход между темами">{prev}{nex}</nav></article><aside class="lesson-toc"><p class="nav-label">В ЭТОЙ ТЕМЕ</p><a href="#theory">01 <span>Кратко о главном</span></a><a href="#example">02 <span>Пример</span></a><a href="#practice">03 <span>Практика</span></a><a href="#quiz">04 <span>Самопроверка</span></a><div class="toc-source">{icon('book')}<strong>Читай глубже</strong><p>Конспект помогает повторить главное. Подробные объяснения и упражнения — в учебнике.</p><a href="../files/informatika-10.pdf#page={x['page']+1}" target="_blank" rel="noopener">Страницы {x['page']}–{x['end']} ↗</a></div></aside></div>'''
    write(f'lessons/{x["id"]:02}.html',layout(x['title'],content,'../',active='group'+str(x['group']),crumb=f'§ {x["id"]}'))

saved=f'''<div class="page-heading"><div><p class="eyebrow">ТВОЯ ПОДБОРКА</p><h1>Избранные темы</h1><p class="page-description">Сохраняй то, к чему хочется вернуться.</p></div></div><div class="saved-page"><div class="lesson-list" data-saved-list>{lesson_rows(LESSONS)}</div><div class="empty-state" data-saved-empty hidden>{icon('bookmark')}<h2>Здесь будут важные темы</h2><p>Нажми на значок закладки рядом с темой, чтобы сохранить её здесь.</p><a class="button button-primary" href="Программисты.html#topics-title">Выбрать тему {icon('arrow')}</a></div></div><div class="source-note">{icon('shield')}<p>Избранное и прогресс хранятся только в этом браузере. Регистрация не нужна. При очистке данных браузера отметки удалятся.</p></div>'''
